//! The generated module's text: the source around the bodies, and the
//! spellings of generated expressions.

use std::collections::BTreeMap;

use baml_compiler2_mir::BinOp;

use crate::{admit::CompiledFunction, analysis::Repr};

const PRELUDE: &str = "\
//! Generated by `baml_compiler2_native`. Do not edit.
#![allow(unused_imports, unused_mut, unused_variables, unused_assignments, unused_labels,
    unused_parens, unreachable_code, unreachable_patterns, non_snake_case, clippy::all,
    clippy::pedantic)]
use bex_vm::{BexVm, NativeFunction, NativeBodyTable, errors::VmError};
use bex_vm::compiled_rt::{CompiledEntry, CompiledFn, Resume, Step};
use bex_vm_types::{BinOp, CmpOp, GlobalIndex, ObjectIndex, RealizedTy, Value};
type R<T> = Result<T, Box<VmError>>;
";

pub(crate) fn render_module(
    bodies: &str,
    functions: &[CompiledFunction],
    natives: &BTreeMap<String, usize>,
    artifact_path: &str,
    fingerprint: [u8; 32],
) -> Result<String, String> {
    let mut out = String::from(PRELUDE);
    for (key, ordinal) in natives {
        out += &format!(
            "fn native_{ordinal}() -> NativeFunction {{
                static F: std::sync::OnceLock<NativeFunction> = std::sync::OnceLock::new();
                *F.get_or_init(|| bex_vm::package_baml::resolve_native({key:?})
                    .expect(\"builtin bound at compile time\"))
            }}\n"
        );
    }
    out += bodies;
    out += &format!(
        "pub static NATIVE_BODIES: NativeBodyTable = NativeBodyTable {{
            fingerprint: {fingerprint:?},
            entries: &[\n"
    );
    for function in functions {
        let shape = if function.resumable {
            "Resumable"
        } else {
            "Inline"
        };
        out += &format!(
            "CompiledEntry {{ object: {}, name: {:?}, arity: {}, body: CompiledFn::{shape}({}), \
             slots: {}, cause_slot: {:?} }},\n",
            function.object,
            function.name,
            function.arity,
            function.symbol,
            function.slots,
            function.cause_slot,
        );
    }
    out += "] };\n";
    out += &format!("pub static PROGRAM_ARTIFACT: &[u8] = include_bytes!({artifact_path:?});\n");
    syn::parse_file(&out)
        .map(|file| prettyplease::unparse(&file))
        .map_err(|error| format!("native backend generated invalid Rust: {error}"))
}

/// Whether generated code `code` is a local, a numeric literal, or a path.
/// Anything else is bound to a temporary before it is used as an argument.
pub(crate) fn is_atom(code: &str) -> bool {
    let token = code.strip_prefix('-').unwrap_or(code);
    !token.is_empty()
        && token
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | ':' | '.'))
}

/// Convert `code`, held as `from`, into `to`.
pub(crate) fn coerce(code: &str, from: Repr, to: Repr) -> String {
    use Repr::{Bool, Float, Int, Value};
    match (from, to) {
        (a, b) if a == b => code.to_string(),
        (Int, Value) => format!("Value::int({code})"),
        (Bool, Value) => format!("Value::bool({code})"),
        (Float, Value) => format!("vm.float_value({code})"),
        // Checked: a value of the wrong kind here is a checker hole, reported
        // as the internal error the interpreter's generic paths raise, never
        // read as zero.
        (Value, Int) => format!("bex_vm::compiled_rt::expect_int({code})?"),
        (Value, Bool) => format!("bex_vm::compiled_rt::expect_bool({code})?"),
        (Value, Float) => format!("bex_vm::compiled_rt::expect_f64({code})?"),
        // Scalars of different kinds never flow into one another in checked
        // MIR; go through the tagged form so the VM's own rule decides.
        (a, b) => coerce(&coerce(code, a, Value), Value, b),
    }
}

pub(crate) fn float_literal(f: f64) -> String {
    if f.is_nan() {
        "f64::NAN".to_string()
    } else if f.is_infinite() {
        if f > 0.0 {
            "f64::INFINITY".to_string()
        } else {
            "f64::NEG_INFINITY".to_string()
        }
    } else {
        format!("{f:?}f64")
    }
}

pub(crate) fn cmp_name(op: BinOp) -> &'static str {
    match op {
        BinOp::Eq => "Eq",
        BinOp::Ne => "NotEq",
        BinOp::Lt => "Lt",
        BinOp::Le => "LtEq",
        BinOp::Gt => "Gt",
        BinOp::Ge => "GtEq",
        _ => unreachable!("not a comparison"),
    }
}

pub(crate) fn binop_name(op: BinOp) -> &'static str {
    match op {
        BinOp::Add => "Add",
        BinOp::Sub => "Sub",
        BinOp::Mul => "Mul",
        BinOp::Div => "Div",
        BinOp::Mod => "Mod",
        BinOp::BitAnd => "BitAnd",
        BinOp::BitOr => "BitOr",
        BinOp::BitXor => "BitXor",
        BinOp::Shl => "Shl",
        BinOp::Shr => "Shr",
        _ => unreachable!("not an arithmetic operator"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn malformed_generated_rust_is_an_error() {
        let error = render_module("fn broken(", &[], &BTreeMap::new(), "program.bexa", [0; 32])
            .unwrap_err();
        assert!(error.starts_with("native backend generated invalid Rust"));
    }

    #[test]
    fn float_literals_round_trip() {
        assert_eq!(float_literal(1.0), "1.0f64");
        assert_eq!(float_literal(f64::NAN), "f64::NAN");
        assert_eq!(float_literal(f64::NEG_INFINITY), "f64::NEG_INFINITY");
    }
}
